from rich.traceback import install
import sys

install()

def test_notes():
    try:
        try:
            raise ValueError("Original error")
        except ValueError as e:
            e.__notes__ = "This is a note"
            raise e
    except Exception:
        # The install() hook should handle this, but we are in a script
        # so we might need to trigger the excepthook manually or just let it crash.
        # Since we called install(), the sys.excepthook is replaced.
        # However, we are catching it here.
        # Let's just raise it and let sys.excepthook handle it.
        raise

if __name__ == "__main__":
    try:
        test_notes()
    except Exception:
        # This will trigger the rich excepthook
        sys.excepthook(*sys.exc_info())

