from rich.traceback import install
import sys

install()

def test_syntax_notes():
    try:
        try:
            # Force a SyntaxError
            compile("if True", "<string>", "exec") # This is fine
            # We need to actually raise a SyntaxError
            raise SyntaxError("Invalid syntax")
        except SyntaxError as e:
            e.__notes__ = "Syntax note"
            raise e
    except Exception:
        raise

if __name__ == "__main__":
    try:
        test_syntax_notes()
    except Exception:
        sys.excepthook(*sys.exc_info())
